// ServerInterface represents all server handlers.
type ServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(w http.ResponseWriter, r *http.Request)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(w http.ResponseWriter, r *http.Request)
	// 取得可恢复的数据屏障
	// (POST /v1/barriers)
	AcquireBarrier(w http.ResponseWriter, r *http.Request)
	// 释放屏障
	// (DELETE /v1/barriers/{barrierId})
	ReleaseBarrier(w http.ResponseWriter, r *http.Request, barrierId Identifier)
	// 文档及回收站分页列表
	// (GET /v1/documents)
	ListDocuments(w http.ResponseWriter, r *http.Request, params ListDocumentsParams)
	// 新建共享草稿文档
	// (POST /v1/documents)
	CreateDocument(w http.ResponseWriter, r *http.Request)
	// 读取全篇共享草稿及编辑状态
	// (GET /v1/documents/{documentId}/draft)
	ReadDraft(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 自动保存完整Tiptap正文
	// (PUT /v1/documents/{documentId}/draft)
	SaveDraft(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 查看署名发布/git版本历史
	// (GET /v1/documents/{documentId}/history)
	ReadRevisionHistory(w http.ResponseWriter, r *http.Request, documentId Identifier, params ReadRevisionHistoryParams)
	// 按稳定块ID对比历史版本
	// (POST /v1/documents/{documentId}/history:diff)
	DiffRevisions(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 回滚历史形成新发布/git提交
	// (POST /v1/documents/{documentId}/history:rollback)
	RollbackPublishedRevision(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 关闭页面释放自身锁
	// (DELETE /v1/documents/{documentId}/lock)
	ReleaseEditLock(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 打开文档自动获得内存编辑锁
	// (POST /v1/documents/{documentId}/lock)
	AcquireEditLock(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 心跳维持锁并处理长时间无输入
	// (PUT /v1/documents/{documentId}/lock)
	RenewEditLock(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 只有超管强制释放别人锁
	// (POST /v1/documents/{documentId}/lock:force-release)
	ForceReleaseEditLock(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 修改标题/路径/SEO描述/分享图
	// (PUT /v1/documents/{documentId}/metadata)
	UpdateDocumentMetadata(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 获取仍公开的精确正文快照
	// (GET /v1/documents/{documentId}/published)
	ReadPublishedRevision(w http.ResponseWriter, r *http.Request, documentId Identifier, params ReadPublishedRevisionParams)
	// 点击发布才公开精确共享草稿版本
	// (POST /v1/documents/{documentId}:publish)
	PublishDocument(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 从回收站恢复为草稿
	// (POST /v1/documents/{documentId}:restore)
	RestoreDocument(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 删除进回收站，可选旧URL替代跳转
	// (POST /v1/documents/{documentId}:trash)
	TrashDocument(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 撤回后回草稿并让公开页面下线
	// (POST /v1/documents/{documentId}:withdraw)
	WithdrawDocument(w http.ResponseWriter, r *http.Request, documentId Identifier)
	// 经对象API读取私有文件而不共享目录
	// (GET /v1/objects/{objectId})
	ReadContentObject(w http.ResponseWriter, r *http.Request, objectId Identifier, params ReadContentObjectParams)
	// 管理员预览草稿公开样式
	// (POST /v1/previews)
	CreatePreviewGrant(w http.ResponseWriter, r *http.Request)
	// 只向对应管理员验证草稿预览
	// (POST /v1/previews:validate)
	ValidatePreviewGrant(w http.ResponseWriter, r *http.Request)
	// 解析301/410公开路径
	// (GET /v1/public-path:resolve)
	ResolvePublicPath(w http.ResponseWriter, r *http.Request, params ResolvePublicPathParams)
	// 读取公开导航
	// (GET /v1/public-tree)
	ReadPublicTree(w http.ResponseWriter, r *http.Request)
	// 同步核公开引用是否仍可见且当前
	// (POST /v1/publications:validate)
	ValidatePublications(w http.ResponseWriter, r *http.Request)
	// 读取资源引用源持久提交决定
	// (GET /v1/reference-decisions/{sourceOperationId})
	ReadReferenceDecision(w http.ResponseWriter, r *http.Request, sourceOperationId Identifier)
	// 向资源库列出哪些文档引用文件
	// (GET /v1/resource-references)
	ListResourceReferences(w http.ResponseWriter, r *http.Request, params ListResourceReferencesParams)
	// 受控读取已完成域快照归档
	// (GET /v1/snapshots/{snapshotId}/archive)
	ReadSnapshotArchive(w http.ResponseWriter, r *http.Request, snapshotId Identifier, params ReadSnapshotArchiveParams)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(w http.ResponseWriter, r *http.Request)
	// 导出屏障水位的一致快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(w http.ResponseWriter, r *http.Request)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(w http.ResponseWriter, r *http.Request)
	// 只有超管彻底删除/清空回收站
	// (POST /v1/trash:purge)
	PurgeDocuments(w http.ResponseWriter, r *http.Request)
	// 后台读取整站文档树
	// (GET /v1/tree)
	ReadDocumentTree(w http.ResponseWriter, r *http.Request)
	// 拖拽移动层级和顺序
	// (POST /v1/tree:move)
	MoveDocument(w http.ResponseWriter, r *http.Request)
	// 拖拽调整同级顺序
	// (POST /v1/tree:reorder)
	ReorderChildren(w http.ResponseWriter, r *http.Request)
}

